'use client';

import { useEffect, useMemo, useRef, useState } from 'react';

import {
  useAutoplay,
  type AutoplayStep,
} from '@/registry/ndeko/hooks/use-autoplay';
import { Segments, type Segment } from '@/registry/ndeko/ui/segments';

import { DemoBand } from './_parts/demo-band';
import { AT_REST, NEXT_FRAME } from './_parts/frame-loop';
import { DEFAULT_HUE } from './_parts/hue';
import { clamp, shareOf, towards, type Point } from './_parts/math';
import type { Scene } from './_parts/stage';
import { StageCanvas, type StageHandle } from './_parts/stage-canvas';
import { wipeSurface, type Inks, type Surface } from './_parts/surface';

export type DitherMode = 'pointer' | 'horizon' | 'noise';

const DEFAULT_CELL = 6;

const MIN_CELL = 4;

/** The 4 by 4 ordered dither: the rank at which each cell of a tile lights up as the light grows. */
const BAYER = [0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5];

const BAYER_SIDE = 4;

function thresholdOf(rank: number) {
  const centred = rank + 0.5;
  return centred / BAYER.length;
}

const THRESHOLDS = BAYER.map(thresholdOf);

/** A dot takes a third of its cell, and never less than two pixels. */
const DOT_SHARE = 3;

const MIN_DOT = 2;

/** Dots are small and stay a tint: text sits above them and must stay easy to read. */
const DOT_ALPHA = 0.6;

/** The light never fills every cell: a few dots stay dark even at its heart, so it keeps a grain. */
const PEAK = 0.92;

/** Seconds for a cell to follow the light most of the way: a change of mode fades instead of cutting. */
const CELL_EASE_S = 0.2;

const SETTLED = 0.004;

const LIGHT_REACH_PX = 250;

const LIGHT_REACH_SQUARED = LIGHT_REACH_PX * LIGHT_REACH_PX;

const LIGHT_EASE_S = 0.3;

const LIGHT_HOME_PX = 0.5;

/** Without a pointer the light walks a slow loop, so the piece shows what it does by itself. */
const WALK_ACROSS = 0.3;

const WALK_DOWN = 0.22;

const WALK_ACROSS_SPEED = 0.31;

const WALK_DOWN_SPEED = 0.47;

const WALK_DOWN_PHASE = 1.3;

/** The share of the height the horizon light fills once it has risen. */
const HORIZON_SHARE = 0.52;

const HORIZON_RISE_S = 0.9;

const HORIZON_BREATH = 0.04;

const HORIZON_BREATH_SPEED = 0.5;

/** The share of the height over which the light grows from nothing to its peak, below the horizon. */
const HORIZON_SPAN_SHARE = 0.44;

const SWELL_PX = 12;

const SWELL_WAVE = 0.014;

const SWELL_SPEED = 0.6;

type Wave = {
  /** Radians a pixel: how tight the wave is. */
  wave: number;
  /** Radians a second: how fast it travels, and which way. */
  speed: number;
};

/** Four travelling waves add up to the noise: across, down and along both diagonals. */
const NOISE_ACROSS: Wave = { wave: 0.021, speed: 0.42 };

const NOISE_DOWN: Wave = { wave: 0.029, speed: -0.33 };

const NOISE_FALLING: Wave = { wave: 0.013, speed: 0.27 };

const NOISE_RISING: Wave = { wave: 0.017, speed: -0.21 };

const NOISE_GAIN = 0.21;

/** Where the light rests in the still picture, across and down the box. */
const STILL_AT: Point = { x: 0.5, y: 0.42 };

const STILL_CLOCK = 2.4;

const NO_INKS: Inks = { hue: 'transparent', line: 'transparent' };

type DitherField = {
  cell: number;
  dot: number;
  inset: number;
  mode: DitherMode;
  isStill: boolean;
  inks: Inks;
  columns: number;
  rows: number;
  width: number;
  height: number;
  /** The light each cell should show, and the light it shows now on its way there. */
  target: Float32Array;
  shown: Float32Array;
  /** What is on the canvas: 1 where a dot is drawn. */
  lit: Uint8Array;
  clock: number;
  light: Point;
  pointer: Point;
  hasPointer: boolean;
  horizonRise: number;
  edge: Float32Array;
  across: Float32Array;
  down: Float32Array;
  falling: Float32Array;
  rising: Float32Array;
};

function fieldOf(size: number): DitherField {
  const rounded = Math.round(size);
  const cell = Math.max(MIN_CELL, rounded);
  const third = Math.round(cell / DOT_SHARE);
  const dot = Math.max(MIN_DOT, third);
  const margin = cell - dot;
  const inset = Math.floor(margin / 2);
  return {
    cell,
    dot,
    inset,
    mode: 'pointer',
    isStill: false,
    inks: NO_INKS,
    columns: 0,
    rows: 0,
    width: 0,
    height: 0,
    target: new Float32Array(0),
    shown: new Float32Array(0),
    lit: new Uint8Array(0),
    clock: 0,
    light: { x: 0, y: 0 },
    pointer: { x: 0, y: 0 },
    hasPointer: false,
    horizonRise: 1,
    edge: new Float32Array(0),
    across: new Float32Array(0),
    down: new Float32Array(0),
    falling: new Float32Array(0),
    rising: new Float32Array(0),
  };
}

/** The middle of a cell, counted in cells from the edge of the box. */
function centreOf(field: DitherField, cells: number) {
  const start = cells * field.cell;
  const half = field.cell / 2;
  return start + half;
}

/** A share of the box that swings around its middle as the clock runs. */
function swingOf(clock: number, speed: number, phase: number, reach: number) {
  const turned = clock * speed;
  const turn = turned + phase;
  const swing = Math.sin(turn);
  const offset = swing * reach;
  return 0.5 + offset;
}

function walkOf(field: DitherField): Point {
  const across = swingOf(field.clock, WALK_ACROSS_SPEED, 0, WALK_ACROSS);
  const down = swingOf(
    field.clock,
    WALK_DOWN_SPEED,
    WALK_DOWN_PHASE,
    WALK_DOWN
  );
  const x = field.width * across;
  const y = field.height * down;
  return { x, y };
}

function goalOf(field: DitherField) {
  if (field.hasPointer) {
    return field.pointer;
  }
  return walkOf(field);
}

function restLight(field: DitherField) {
  field.light.x = field.width * STILL_AT.x;
  field.light.y = field.height * STILL_AT.y;
}

function glowOf(squared: number) {
  if (squared >= LIGHT_REACH_SQUARED) {
    return 0;
  }
  const distance = Math.sqrt(squared);
  const farness = distance / LIGHT_REACH_PX;
  const nearness = 1 - farness;
  const soft = nearness * nearness;
  return soft * PEAK;
}

/** A light around one point, falling off to nothing at its reach. */
function aimPointer(field: DitherField) {
  const { columns, rows, light, target } = field;
  let index = 0;
  for (let row = 0; row < rows; row += 1) {
    const y = centreOf(field, row);
    const offsetY = y - light.y;
    const squaredY = offsetY * offsetY;
    for (let column = 0; column < columns; column += 1) {
      const x = centreOf(field, column);
      const offsetX = x - light.x;
      const squaredX = offsetX * offsetX;
      const squared = squaredX + squaredY;
      target[index] = glowOf(squared);
      index += 1;
    }
  }
}

/** Where the horizon stands now, in pixels from the top: it rises once, then breathes. */
function horizonOf(field: DitherField) {
  const breathTurn = field.clock * HORIZON_BREATH_SPEED;
  const swing = Math.sin(breathTurn);
  const breath = swing * HORIZON_BREATH;
  const risen = HORIZON_SHARE * field.horizonRise;
  const filled = risen + breath;
  const empty = 1 - filled;
  return field.height * empty;
}

/** A light that rises from the bottom edge. Its upper edge swells along the width. */
function aimHorizon(field: DitherField) {
  const { columns, rows, edge, target } = field;
  const level = horizonOf(field);
  const span = field.height * HORIZON_SPAN_SHARE;
  const drift = field.clock * SWELL_SPEED;
  for (let column = 0; column < columns; column += 1) {
    const x = centreOf(field, column);
    const along = x * SWELL_WAVE;
    const turn = along + drift;
    const swell = Math.sin(turn) * SWELL_PX;
    edge[column] = level + swell;
  }
  let index = 0;
  for (let row = 0; row < rows; row += 1) {
    const y = centreOf(field, row);
    for (let column = 0; column < columns; column += 1) {
      const depth = y - edge[column];
      const reach = depth / span;
      const share = clamp(reach, 0, 1);
      target[index] = share * PEAK;
      index += 1;
    }
  }
}

/** One wave, worked out once for every row, column or diagonal it crosses. */
function fillBand(
  band: Float32Array,
  field: DitherField,
  firstCell: number,
  wave: Wave
) {
  const drift = field.clock * wave.speed;
  const turnPerCell = field.cell * wave.wave;
  for (let index = 0; index < band.length; index += 1) {
    const cells = index + firstCell;
    const along = cells * turnPerCell;
    const turn = along + drift;
    band[index] = Math.sin(turn);
  }
}

/**
 * Four waves that travel across, down and along both diagonals. Each depends on one number a
 * cell, so a cell only adds four numbers that were worked out once a row, a column or a diagonal.
 */
function aimNoise(field: DitherField) {
  const { columns, rows, across, down, falling, rising, target } = field;
  fillBand(across, field, 0, NOISE_ACROSS);
  fillBand(down, field, 0, NOISE_DOWN);
  fillBand(falling, field, 0, NOISE_FALLING);
  fillBand(rising, field, -rows, NOISE_RISING);
  let index = 0;
  for (let row = 0; row < rows; row += 1) {
    const firstRising = rows - row;
    for (let column = 0; column < columns; column += 1) {
      const fallingIndex = column + row;
      const risingIndex = column + firstRising;
      const straight = across[column] + down[row];
      const diagonal = falling[fallingIndex] + rising[risingIndex];
      const sum = straight + diagonal;
      const swing = sum * NOISE_GAIN;
      const centred = 0.5 + swing;
      const level = clamp(centred, 0, 1);
      target[index] = level * PEAK;
      index += 1;
    }
  }
}

function aim(field: DitherField) {
  if (field.mode === 'horizon') {
    aimHorizon(field);
    return;
  }
  if (field.mode === 'noise') {
    aimNoise(field);
    return;
  }
  aimPointer(field);
}

function dotOn(
  pen: CanvasRenderingContext2D,
  field: DitherField,
  column: number,
  row: number
) {
  const cellX = column * field.cell;
  const cellY = row * field.cell;
  const x = cellX + field.inset;
  const y = cellY + field.inset;
  pen.fillRect(x, y, field.dot, field.dot);
}

/** The whole cell is wiped, not the dot alone: on a screen of uneven density a dot leaves a rim. */
function dotOff(
  pen: CanvasRenderingContext2D,
  field: DitherField,
  column: number,
  row: number
) {
  const x = column * field.cell;
  const y = row * field.cell;
  pen.clearRect(x, y, field.cell, field.cell);
}

function isLitAt(
  field: DitherField,
  index: number,
  column: number,
  row: number
) {
  const tileRow = row % BAYER_SIDE;
  const tileColumn = column % BAYER_SIDE;
  const firstOfRow = tileRow * BAYER_SIDE;
  const rank = firstOfRow + tileColumn;
  return field.shown[index] > THRESHOLDS[rank];
}

/**
 * Every cell eases towards its light, and only a dot that crosses its threshold is drawn or wiped.
 * It answers whether any cell is still on its way.
 */
function easeCells(field: DitherField, surface: Surface, share: number) {
  const { columns, rows, target, shown, lit } = field;
  const { pen } = surface;
  let isEasing = false;
  let index = 0;
  pen.fillStyle = field.inks.hue;
  pen.globalAlpha = DOT_ALPHA;
  for (let row = 0; row < rows; row += 1) {
    for (let column = 0; column < columns; column += 1) {
      const gap = target[index] - shown[index];
      const step = gap * share;
      const isOnItsWay = Math.abs(gap) > SETTLED;
      shown[index] += step;
      isEasing = isEasing || isOnItsWay;
      const isLit = isLitAt(field, index, column, row);
      const wasLit = lit[index] === 1;
      if (isLit && !wasLit) {
        dotOn(pen, field, column, row);
        lit[index] = 1;
      }
      if (wasLit && !isLit) {
        dotOff(pen, field, column, row);
        lit[index] = 0;
      }
      index += 1;
    }
  }
  return isEasing;
}

function drawDots(field: DitherField, surface: Surface) {
  const { columns, rows, lit } = field;
  const { pen } = surface;
  let index = 0;
  wipeSurface(surface);
  pen.fillStyle = field.inks.hue;
  pen.globalAlpha = DOT_ALPHA;
  for (let row = 0; row < rows; row += 1) {
    for (let column = 0; column < columns; column += 1) {
      const isLit = isLitAt(field, index, column, row);
      lit[index] = Number(isLit);
      if (isLit) {
        dotOn(pen, field, column, row);
      }
      index += 1;
    }
  }
}

/** The still picture of the current mode: the light at rest, every cell already where it is going. */
function poseStill(field: DitherField) {
  field.clock = STILL_CLOCK;
  field.horizonRise = 1;
  restLight(field);
  aim(field);
  field.shown.set(field.target);
}

function layCells(field: DitherField, surface: Surface, isStill: boolean) {
  const columns = Math.ceil(surface.width / field.cell);
  const rows = Math.ceil(surface.height / field.cell);
  const count = columns * rows;
  const diagonals = columns + rows;
  field.columns = columns;
  field.rows = rows;
  field.width = surface.width;
  field.height = surface.height;
  field.isStill = isStill;
  field.hasPointer = false;
  field.target = new Float32Array(count);
  field.shown = new Float32Array(count);
  field.lit = new Uint8Array(count);
  field.edge = new Float32Array(columns);
  field.across = new Float32Array(columns);
  field.down = new Float32Array(rows);
  field.falling = new Float32Array(diagonals);
  field.rising = new Float32Array(diagonals);
  restLight(field);
  aim(field);
  field.shown.set(field.target);
}

/** The light eases after its goal. It answers whether it is still on its way. */
function moveLight(field: DitherField, seconds: number) {
  const goal = goalOf(field);
  const share = shareOf(seconds, LIGHT_EASE_S);
  field.light.x = towards(field.light.x, goal.x, share);
  field.light.y = towards(field.light.y, goal.y, share);
  const offsetX = goal.x - field.light.x;
  const offsetY = goal.y - field.light.y;
  const distance = Math.hypot(offsetX, offsetY);
  return distance > LIGHT_HOME_PX;
}

/** The horizon and the noise never rest. The pointer light rests once it has reached a pointer that stays still. */
function stepDots(field: DitherField, surface: Surface, seconds: number) {
  if (field.isStill) {
    return AT_REST;
  }
  field.clock += seconds;
  const riseShare = shareOf(seconds, HORIZON_RISE_S);
  field.horizonRise = towards(field.horizonRise, 1, riseShare);
  const isTravelling = moveLight(field, seconds);
  aim(field);
  const cellShare = shareOf(seconds, CELL_EASE_S);
  const isEasing = easeCells(field, surface, cellShare);
  const isLed = field.mode === 'pointer' && field.hasPointer;
  const isMoving = isTravelling || isEasing;
  if (isLed && !isMoving) {
    return AT_REST;
  }
  return NEXT_FRAME;
}

type DitherScene = Scene & {
  setMode: (mode: DitherMode) => void;
};

function createDitherScene(size: number): DitherScene {
  const field = fieldOf(size);
  return {
    ink(inks) {
      field.inks = inks;
    },
    fit(surface, isStill) {
      layCells(field, surface, isStill);
    },
    draw(surface) {
      if (field.isStill) {
        poseStill(field);
      }
      drawDots(field, surface);
    },
    step(surface, seconds) {
      return stepDots(field, surface, seconds);
    },
    pointerMoved(x, y) {
      field.pointer.x = x;
      field.pointer.y = y;
      field.hasPointer = true;
    },
    pointerLeft() {
      field.hasPointer = false;
    },
    setMode(mode) {
      const isNewHorizon = mode === 'horizon' && field.mode !== 'horizon';
      field.mode = mode;
      if (isNewHorizon) {
        field.horizonRise = 0;
      }
    },
  };
}

export type DitherLightProps = {
  className?: string;
  /** Any colour token, such as `var(--primary)` or `var(--series-2)`. The dots wear it. */
  hue?: string;
  /** A glow that follows the pointer, a light that rises from the bottom edge, or noise that flows. */
  mode?: DitherMode;
  /** The side of a dither cell, in pixels. */
  size?: number;
  /** In `pointer` mode the glow follows the pointer. Without it, the glow walks by itself. */
  interactive?: boolean;
};

/**
 * A soft light drawn as crisp dots: a 4 by 4 ordered dither of a light field, on one canvas. Each
 * frame only draws or wipes the dots that cross their threshold. It fills its parent, which must
 * be positioned. Under reduced motion the light stands still.
 */
export function DitherLight({
  className,
  hue = DEFAULT_HUE,
  mode = 'pointer',
  size = DEFAULT_CELL,
  interactive = true,
}: DitherLightProps) {
  const stage = useRef<StageHandle>(null);
  const scene = useMemo(() => createDitherScene(size), [size]);

  useEffect(() => {
    scene.setMode(mode);
    stage.current?.refresh();
  }, [scene, mode]);

  return (
    <StageCanvas
      handleRef={stage}
      scene={scene}
      hue={hue}
      isInteractive={interactive}
      className={className}
    />
  );
}

const MODES: Segment<DitherMode>[] = [
  { value: 'pointer', label: 'Pointer' },
  { value: 'horizon', label: 'Horizon' },
  { value: 'noise', label: 'Noise' },
];

/** Long enough to see a mode move before the demonstration shows the next one. */
const MODE_HOLD_MS = 5200;

export default function Background03() {
  const [mode, setMode] = useState<DitherMode>('pointer');
  const steps: AutoplayStep[] = [
    { after: MODE_HOLD_MS, run: () => setMode('horizon') },
    { after: MODE_HOLD_MS, run: () => setMode('noise') },
    { after: MODE_HOLD_MS, run: () => setMode('pointer') },
  ];
  const { ref } = useAutoplay<HTMLElement>(steps, { loopAfter: 0 });

  return (
    <DemoBand
      ref={ref}
      title='One light, drawn in dots'
      background={<DitherLight mode={mode} />}
    >
      <Segments
        value={mode}
        segments={MODES}
        onValueChange={setMode}
        label='How the light moves'
        className='bg-card hairline-ring ring-border'
      />
    </DemoBand>
  );
}

import { useId, type ReactNode, type Ref } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';

type BandAlign = 'center' | 'end';

const ALIGNMENTS: Record<BandAlign, string> = {
  center: 'justify-center',
  end: 'justify-end pb-10',
};

type DemoBandProps = {
  ref?: Ref<HTMLElement>;
  title: string;
  /** The background under test. It fills the band, behind the headline and the actions. */
  background: ReactNode;
  /** `end` sets the headline at the foot of the band and leaves its middle to the background. */
  align?: BandAlign;
  children: ReactNode;
};

/**
 * The band every background is shown in: the page colour, a headline in the foreground colour and
 * the actions laid straight over the background, to prove that text stays readable above it.
 */
export function DemoBand({
  ref,
  title,
  background,
  align = 'center',
  children,
}: DemoBandProps) {
  const titleId = useId();

  return (
    <section
      ref={ref}
      aria-labelledby={titleId}
      className={cn(
        'bg-background @container relative isolate flex h-90 w-full flex-col items-center overflow-hidden rounded-xl',
        ALIGNMENTS[align]
      )}
    >
      {background}
      <div className='relative flex max-w-lg flex-col items-center gap-5 px-6 text-center'>
        <h3
          id={titleId}
          className='text-2xl font-semibold text-balance @lg:text-3xl'
        >
          {title}
        </h3>
        <div className='flex flex-wrap items-center justify-center gap-2'>
          {children}
        </div>
      </div>
    </section>
  );
}

const FRAMES_PER_SECOND = 30;

const FRAME_MS = 1000 / FRAMES_PER_SECOND;

/**
 * The timer between two frames ends this long before the next one is due, so the frame it asks for
 * lands on the screen refresh that is due and not on the one after.
 */
const REFRESH_LEAD_MS = 5;

const TIMER_MS = FRAME_MS - REFRESH_LEAD_MS;

/** A frame that comes late, after a long task, moves the picture no further than this long would. */
const MAX_STEP_S = 0.05;

/** What a frame answers while the picture still moves: the next one comes as soon as the cap allows. */
export const NEXT_FRAME = 0;

/** What a frame answers once the picture has come to rest: nothing is asked for until `wake`. */
export const AT_REST = Number.POSITIVE_INFINITY;

/** Draws one frame, `seconds` after the last one, and answers how many milliseconds it can wait for the next. */
export type FrameHandler = (seconds: number, now: number) => number;

export type FrameLoop = {
  start: () => void;
  stop: () => void;
  wake: () => void;
};

/**
 * Frames at thirty a second at most. Between two frames there is one timer and no animation frame,
 * so a 120 Hz screen does not run four rounds of main-thread work for one frame drawn. Stopped or
 * at rest, the loop holds no timer and asks for no frame.
 */
export function createFrameLoop(onFrame: FrameHandler): FrameLoop {
  let frame = 0;
  let timer: ReturnType<typeof setTimeout> | undefined;
  let isStarted = false;
  let lastFrameAt = 0;

  function clearPending() {
    cancelAnimationFrame(frame);
    clearTimeout(timer);
    frame = 0;
    timer = undefined;
  }

  function askForFrame() {
    timer = undefined;
    frame = requestAnimationFrame(tick);
  }

  function schedule(wait: number) {
    clearPending();
    const now = performance.now();
    const sinceFrame = now - lastFrameAt;
    const untilCap = TIMER_MS - sinceFrame;
    const delay = Math.max(wait, untilCap);
    if (delay <= 0) {
      askForFrame();
      return;
    }
    timer = setTimeout(askForFrame, delay);
  }

  function tick(now: number) {
    frame = 0;
    const elapsedMs = now - lastFrameAt;
    const elapsed = elapsedMs / 1000;
    const forward = Math.max(0, elapsed);
    const seconds = Math.min(forward, MAX_STEP_S);
    lastFrameAt = now;
    const wait = onFrame(seconds, now);
    const isResting = wait === AT_REST;
    if (isResting || !isStarted) {
      return;
    }
    schedule(wait);
  }

  function start() {
    if (isStarted) {
      return;
    }
    const now = performance.now();
    isStarted = true;
    lastFrameAt = now - FRAME_MS;
    schedule(NEXT_FRAME);
  }

  function stop() {
    isStarted = false;
    clearPending();
  }

  function wake() {
    const isFrameComing = frame !== 0;
    if (!isStarted || isFrameComing) {
      return;
    }
    schedule(NEXT_FRAME);
  }

  return { start, stop, wake };
}

'use client';

import { useState } from 'react';

/** A background wears one hue: the brand unless it is told otherwise. */
export const DEFAULT_HUE = 'var(--primary)';

/** The brand first, then the series hues that differ from it. */
const DEMO_HUES = [
  DEFAULT_HUE,
  'var(--series-2)',
  'var(--series-3)',
  'var(--series-4)',
  'var(--series-5)',
];

/** The hue of a demo, and the step to the next one, to show a background in each hue it accepts. */
export function useHueCycle() {
  const [index, setIndex] = useState(0);
  const hue = DEMO_HUES[index] ?? DEFAULT_HUE;

  function nextHue() {
    setIndex((current) => {
      const next = current + 1;
      return next % DEMO_HUES.length;
    });
  }

  return { hue, nextHue };
}

export type Point = {
  x: number;
  y: number;
};

export function clamp(value: number, low: number, high: number) {
  const raised = Math.max(low, value);
  return Math.min(high, raised);
}

/** How much of the way left is covered in `seconds`: the same glide whatever the frame rate. */
export function shareOf(seconds: number, easeSeconds: number) {
  const ratio = seconds / easeSeconds;
  const decay = Math.exp(-ratio);
  return 1 - decay;
}

export function towards(from: number, to: number, share: number) {
  const gap = to - from;
  const step = gap * share;
  return from + step;
}

/** From 0 at `low` to 1 at `high`, leaving and arriving without a corner. */
export function smoothstep(low: number, high: number, value: number) {
  const span = high - low;
  const offset = value - low;
  const raw = offset / span;
  const share = clamp(raw, 0, 1);
  const doubled = 2 * share;
  const curve = 3 - doubled;
  const squared = share * share;
  return squared * curve;
}

/** The damping that brings a spring of this stiffness to its target without passing it. */
export function dampingOf(stiffness: number) {
  const root = Math.sqrt(stiffness);
  return 2 * root;
}

/**
 * The speed of a spring one step later. The caller then moves the value by that speed over the
 * same step, so the value follows its target and settles on it.
 */
export function springSpeedOf(
  gap: number,
  speed: number,
  stiffness: number,
  damping: number,
  seconds: number
) {
  const pull = gap * stiffness;
  const drag = speed * damping;
  const push = pull - drag;
  const gain = push * seconds;
  return speed + gain;
}

import type { Point } from './math';

/**
 * Where a point of the window falls inside `host`, in the pixels of its own box, or null when it
 * falls outside. A host that an ancestor scales still answers in its own pixels.
 */
export function placeIn(
  host: HTMLElement,
  clientX: number,
  clientY: number
): Point | null {
  const box = host.getBoundingClientRect();
  const isEmpty = box.width === 0 || box.height === 0;
  if (isEmpty) {
    return null;
  }
  const isInsideX = clientX >= box.left && clientX <= box.right;
  const isInsideY = clientY >= box.top && clientY <= box.bottom;
  if (!isInsideX || !isInsideY) {
    return null;
  }
  const scaleX = host.offsetWidth / box.width;
  const scaleY = host.offsetHeight / box.height;
  const offsetX = clientX - box.left;
  const offsetY = clientY - box.top;
  const x = offsetX * scaleX;
  const y = offsetY * scaleY;
  return { x, y };
}

/** Where the centre of `element` falls inside `host`, or null when it falls outside. */
export function centreIn(host: HTMLElement, element: Element) {
  const box = element.getBoundingClientRect();
  const halfWidth = box.width / 2;
  const halfHeight = box.height / 2;
  const centreX = box.left + halfWidth;
  const centreY = box.top + halfHeight;
  return placeIn(host, centreX, centreY);
}

/**
 * Follows a pointer that can hover, from the window: content laid over a background takes the
 * pointer events of its own box, so a listener on the background would go blind under a headline.
 * The place is read once a frame at most, and only on a frame where the pointer moved. `onMove`
 * gets the place inside `host`; `onLeave` is called once when the pointer goes out of it. The
 * function returned ends the watch, and lets go of a pointer that was still over the host.
 */
export function watchPointer(
  host: HTMLElement,
  onMove: (x: number, y: number) => void,
  onLeave: () => void
) {
  let clientX = 0;
  let clientY = 0;
  let frame = 0;
  let isOver = false;

  function leave() {
    if (!isOver) {
      return;
    }
    isOver = false;
    onLeave();
  }

  function read() {
    frame = 0;
    const place = placeIn(host, clientX, clientY);
    if (!place) {
      leave();
      return;
    }
    isOver = true;
    onMove(place.x, place.y);
  }

  function onPointerMove(event: PointerEvent) {
    const isTouch = event.pointerType === 'touch';
    if (isTouch) {
      return;
    }
    clientX = event.clientX;
    clientY = event.clientY;
    const isReadComing = frame !== 0;
    if (isReadComing) {
      return;
    }
    frame = requestAnimationFrame(read);
  }

  function onPointerGone() {
    cancelAnimationFrame(frame);
    frame = 0;
    leave();
  }

  const root = document.documentElement;
  window.addEventListener('pointermove', onPointerMove, { passive: true });
  root.addEventListener('pointerleave', onPointerGone, { passive: true });

  return () => {
    window.removeEventListener('pointermove', onPointerMove);
    root.removeEventListener('pointerleave', onPointerGone);
    onPointerGone();
  };
}

/**
 * A background sits behind content for as long as the page is open, so everything it runs hangs on
 * this answer: its box touches the screen and the tab is the one looked at. `onChange` is called
 * each time the answer changes, starting from "not showing". The function returned ends the watch.
 */
export function watchShowing(
  element: Element,
  onChange: (isShowing: boolean) => void
) {
  let isOnScreen = false;
  let wasShowing = false;

  function report() {
    const isTabShown = document.visibilityState === 'visible';
    const isShowing = isOnScreen && isTabShown;
    if (isShowing === wasShowing) {
      return;
    }
    wasShowing = isShowing;
    onChange(isShowing);
  }

  function onCrossing(entries: IntersectionObserverEntry[]) {
    const latest = entries.at(-1);
    if (!latest) {
      return;
    }
    isOnScreen = latest.isIntersecting;
    report();
  }

  const observer = new IntersectionObserver(onCrossing);
  observer.observe(element);
  document.addEventListener('visibilitychange', report);

  return () => {
    observer.disconnect();
    document.removeEventListener('visibilitychange', report);
  };
}

'use client';

import { useEffect, useImperativeHandle, useRef, type Ref } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';

import type { Point } from './math';
import { mountStage, type Scene, type Stage } from './stage';

export type StageHandle = {
  /** Something outside the loop changed the scene: it is drawn again, and its loop is woken. */
  refresh: () => void;
  /** Where the centre of an element sits on the canvas, or null when it is outside. */
  centreOf: (element: Element) => Point | null;
};

type StageCanvasProps = {
  scene: Scene;
  hue: string;
  isInteractive?: boolean;
  className?: string;
  handleRef?: Ref<StageHandle>;
};

/**
 * The one canvas of a background. It fills its parent, lets every pointer event through and is
 * hidden from assistive technology, since it is decoration. A canvas cannot take a colour from a
 * class: the hue rides on its `color` and the neutral of lines on `decoration-foreground`, and the
 * stage reads both from the computed style. No transition may sit on those two, or the stage
 * would read a colour halfway through it.
 */
export function StageCanvas({
  scene,
  hue,
  isInteractive = false,
  className,
  handleRef,
}: StageCanvasProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const stage = useRef<Stage | null>(null);
  const shouldReduceMotion = usePrefersReducedMotion();

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) {
      return;
    }
    const mounted = mountStage(canvas, scene, {
      isStill: shouldReduceMotion,
      isInteractive,
    });
    stage.current = mounted;
    return () => {
      mounted?.dispose();
      stage.current = null;
    };
  }, [scene, isInteractive, shouldReduceMotion]);

  useEffect(() => {
    stage.current?.reink();
  }, [hue]);

  useImperativeHandle(
    handleRef,
    () => ({
      refresh: () => stage.current?.refresh(),
      centreOf: (element) => stage.current?.centreOf(element) ?? null,
    }),
    []
  );

  return (
    <canvas
      ref={canvasRef}
      aria-hidden='true'
      style={{ color: hue }}
      className={cn(
        'decoration-foreground pointer-events-none absolute inset-0 size-full',
        className
      )}
    />
  );
}

import { createFrameLoop } from './frame-loop';
import type { Point } from './math';
import { centreIn, watchPointer } from './pointer';
import { watchShowing } from './showing';
import {
  createSurface,
  fitSurface,
  hasSameInks,
  inksOf,
  isFitted,
  watchSurface,
  type Inks,
  type Surface,
} from './surface';

/** What a background draws on its canvas. The stage decides when; the scene only knows how. */
export type Scene = {
  /** The colours changed: the theme, or the hue. */
  ink: (inks: Inks) => void;
  /**
   * The box changed, and the canvas was wiped: what depends on its size is built again. `isStill`
   * is the reduced motion setting: the scene then holds its most telling picture and never moves.
   */
  fit: (surface: Surface, isStill: boolean) => void;
  /** The whole picture as it stands. */
  draw: (surface: Surface) => void;
  /**
   * Moves the picture on by `seconds` and draws what changed. It answers how long it can wait for
   * its next frame: `NEXT_FRAME`, `AT_REST`, or a number of milliseconds.
   */
  step: (surface: Surface, seconds: number, now: number) => number;
  pointerMoved?: (x: number, y: number) => void;
  pointerLeft?: () => void;
};

export type Stage = {
  /** Something outside the loop changed the scene: it is drawn again, and its loop is woken. */
  refresh: () => void;
  /** Reads the colours again, and draws again when they changed. */
  reink: () => void;
  /** Where the centre of an element sits on the canvas, or null when it is outside. */
  centreOf: (element: Element) => Point | null;
  dispose: () => void;
};

export type StageOptions = {
  /** Reduced motion: no pointer is followed and nothing moves by itself. */
  isStill: boolean;
  isInteractive: boolean;
};

function idle() {}

function stageOf(
  surface: Surface,
  scene: Scene,
  { isStill, isInteractive }: StageOptions
): Stage {
  const { canvas } = surface;
  const followsPointer = isInteractive && !isStill;
  let isShowing = false;
  let stopPointer = idle;
  let inks = inksOf(canvas);

  const loop = createFrameLoop((seconds, now) =>
    scene.step(surface, seconds, now)
  );

  function wake() {
    if (isShowing) {
      loop.wake();
    }
  }

  function lay() {
    fitSurface(surface);
    scene.fit(surface, isStill);
    scene.draw(surface);
  }

  function onPointerMove(x: number, y: number) {
    scene.pointerMoved?.(x, y);
    wake();
  }

  function onPointerLeave() {
    scene.pointerLeft?.();
    wake();
  }

  function show() {
    isShowing = true;
    if (followsPointer) {
      stopPointer = watchPointer(canvas, onPointerMove, onPointerLeave);
    }
    loop.start();
  }

  function hide() {
    isShowing = false;
    stopPointer();
    stopPointer = idle;
    loop.stop();
  }

  function onShowing(isNowShowing: boolean) {
    if (isNowShowing) {
      show();
      return;
    }
    hide();
  }

  function onResize() {
    if (isFitted(surface)) {
      return;
    }
    lay();
    wake();
  }

  function reink() {
    const latest = inksOf(canvas);
    if (hasSameInks(inks, latest)) {
      return;
    }
    inks = latest;
    scene.ink(inks);
    scene.draw(surface);
    wake();
  }

  /** In the loop, the next frame draws the change. Out of it, nothing would, so it is drawn here. */
  function refresh() {
    const isOutOfLoop = isStill || !isShowing;
    if (isOutOfLoop) {
      scene.draw(surface);
    }
    wake();
  }

  scene.ink(inks);
  lay();
  const stopSurface = watchSurface(canvas, onResize, reink);
  const stopShowing = watchShowing(canvas, onShowing);

  return {
    refresh,
    reink,
    centreOf: (element) => centreIn(canvas, element),
    dispose() {
      stopShowing();
      stopSurface();
      hide();
    },
  };
}

/**
 * Puts a scene on a canvas. The stage sizes the canvas for the screen, reads its colours, and runs
 * the loop of the scene only while the canvas is on screen in a visible tab. It draws one frame
 * when it is set up, so the picture is there before anything moves.
 */
export function mountStage(
  canvas: HTMLCanvasElement,
  scene: Scene,
  options: StageOptions
) {
  const surface = createSurface(canvas);
  if (!surface) {
    return null;
  }
  return stageOf(surface, scene, options);
}

/** A backing store above two device pixels a point costs four times the fill for a picture nobody sees sharper. */
const MAX_PIXEL_RATIO = 2;

const THEME_WATCH = {
  attributes: true,
  attributeFilter: ['class', 'data-theme'],
};

const DARK_SCHEME = '(prefers-color-scheme: dark)';

export type Surface = {
  canvas: HTMLCanvasElement;
  pen: CanvasRenderingContext2D;
  /** The box of the canvas in CSS pixels: one unit drawn is one of them, whatever the screen. */
  width: number;
  height: number;
  pixelRatio: number;
};

export type Inks = {
  /** The hue of the background, resolved by the browser for the current theme. */
  hue: string;
  /** The neutral of lines: the foreground of the theme. */
  line: string;
};

export function createSurface(canvas: HTMLCanvasElement): Surface | null {
  const pen = canvas.getContext('2d');
  if (!pen) {
    return null;
  }
  return { canvas, pen, width: 0, height: 0, pixelRatio: 1 };
}

function pixelRatioOf() {
  const devicePixelRatio = window.devicePixelRatio || 1;
  return Math.min(devicePixelRatio, MAX_PIXEL_RATIO);
}

/** Sizes the backing store to the box of the canvas and to the screen. It also wipes the canvas. */
export function fitSurface(surface: Surface) {
  const { canvas, pen } = surface;
  const pixelRatio = pixelRatioOf();
  const width = canvas.clientWidth;
  const height = canvas.clientHeight;
  const deviceWidth = width * pixelRatio;
  const deviceHeight = height * pixelRatio;
  surface.width = width;
  surface.height = height;
  surface.pixelRatio = pixelRatio;
  canvas.width = Math.round(deviceWidth);
  canvas.height = Math.round(deviceHeight);
  pen.setTransform(pixelRatio, 0, 0, pixelRatio, 0, 0);
}

export function isFitted(surface: Surface) {
  const { canvas } = surface;
  const hasWidth = surface.width === canvas.clientWidth;
  const hasHeight = surface.height === canvas.clientHeight;
  const hasRatio = surface.pixelRatio === pixelRatioOf();
  const hasSize = hasWidth && hasHeight;
  return hasSize && hasRatio;
}

export function wipeSurface(surface: Surface) {
  surface.pen.globalAlpha = 1;
  surface.pen.clearRect(0, 0, surface.width, surface.height);
}

/**
 * A canvas cannot take a colour from a class, so it reads its colours from its own computed style,
 * where the browser has already resolved the tokens for the current theme. The hue rides on
 * `color` and the neutral of lines on `text-decoration-color`, which paints nothing on a canvas.
 */
export function inksOf(canvas: HTMLCanvasElement): Inks {
  const style = getComputedStyle(canvas);
  return { hue: style.color, line: style.textDecorationColor };
}

export function hasSameInks(first: Inks, second: Inks) {
  const hasSameHue = first.hue === second.hue;
  const hasSameLine = first.line === second.line;
  return hasSameHue && hasSameLine;
}

function densityQueryOf() {
  return `(resolution: ${window.devicePixelRatio}dppx)`;
}

/**
 * Calls `onResize` when the box of the canvas or the density of the screen changes, and `onTheme`
 * when the page may have changed theme: a class or an attribute on the root or the body, or the
 * system setting. The function returned ends the watch.
 */
export function watchSurface(
  canvas: HTMLCanvasElement,
  onResize: () => void,
  onTheme: () => void
) {
  const sizeObserver = new ResizeObserver(() => onResize());
  const themeObserver = new MutationObserver(() => onTheme());
  const scheme = window.matchMedia(DARK_SCHEME);
  let density = window.matchMedia(densityQueryOf());

  function onScheme() {
    onTheme();
  }

  /** The query names one density: once the screen has left it, a new query watches the next one. */
  function onDensity() {
    density.removeEventListener('change', onDensity);
    density = window.matchMedia(densityQueryOf());
    density.addEventListener('change', onDensity);
    onResize();
  }

  sizeObserver.observe(canvas);
  themeObserver.observe(document.documentElement, THEME_WATCH);
  themeObserver.observe(document.body, THEME_WATCH);
  scheme.addEventListener('change', onScheme);
  density.addEventListener('change', onDensity);

  return () => {
    sizeObserver.disconnect();
    themeObserver.disconnect();
    scheme.removeEventListener('change', onScheme);
    density.removeEventListener('change', onDensity);
  };
}
